import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import api, { type EncodeResponse, type Presets } from "../services/api";

interface AppState {
  /** Last transmission generated by the Transmitter (or Explorer demo). */
  lastEncode: EncodeResponse | null;
  lastEncodeLabel: string | null;
  setLastEncode: (r: EncodeResponse | null, label?: string) => void;
  /** Cached /api/presets (loaded once). */
  presets: Presets | null;
  presetsError: string | null;
  reloadPresets: () => void;
  backendOk: boolean | null;
  backendVersion: string | null;
}

const Ctx = createContext<AppState | null>(null);

export function AppStateProvider({ children }: { children: ReactNode }) {
  const [lastEncode, setLast] = useState<EncodeResponse | null>(null);
  const [lastEncodeLabel, setLabel] = useState<string | null>(null);
  const [presets, setPresets] = useState<Presets | null>(null);
  const [presetsError, setPresetsError] = useState<string | null>(null);
  const [backendOk, setBackendOk] = useState<boolean | null>(null);
  const [backendVersion, setBackendVersion] = useState<string | null>(null);

  const reloadPresets = useCallback(() => {
    setPresetsError(null);
    api
      .presets()
      .then((p) => setPresets(p))
      .catch((e: Error) => setPresetsError(e.message));
    api
      .health()
      .then((h) => {
        setBackendOk(!!h.ok);
        setBackendVersion(h.version);
      })
      .catch(() => setBackendOk(false));
  }, []);

  useEffect(() => {
    reloadPresets();
  }, [reloadPresets]);

  const setLastEncode = useCallback((r: EncodeResponse | null, label?: string) => {
    setLast(r);
    setLabel(label ?? null);
  }, []);

  const value = useMemo<AppState>(
    () => ({ lastEncode, lastEncodeLabel, setLastEncode, presets, presetsError, reloadPresets, backendOk, backendVersion }),
    [lastEncode, lastEncodeLabel, setLastEncode, presets, presetsError, reloadPresets, backendOk, backendVersion]
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useAppState(): AppState {
  const v = useContext(Ctx);
  if (!v) throw new Error("useAppState must be used inside AppStateProvider");
  return v;
}
